import argparseimport loggingimport sysfrom pathlib import Pathfrom sqlalchemy import create_engine, URLimport numpy as npimport pandas as pd# Initialize basic logging so messages show up in the consolelogging.basicConfig(    level=logging.INFO,     format="%(asctime)s - %(levelname)s - %(message)s")def load_data (input_path : str) -> dict[str, int] :# convert input path string into path object    folder = Path(input_path)#validate the folder    if not folder.exists() or not folder.is_dir():          raise FileNotFoundError(f"Input folder does not exist: {folder.resolve()}" )    logging.info(f"Folder exists {folder.resolve()}")#check for csv files    csv_files = sorted(folder.glob("*.csv"))    if not csv_files :        logging.warning( "CSV files not found in {folder} ")        return {}    logging.info( f"Files found  {len(csv_files)} and begin loading to SQL server")#loading the data source to sql server    connection_url = URL.create(        "mssql+pyodbc",        host="localhost",        database="Blinkit_Quick_Commerce",        query={            "driver": "ODBC Driver 18 for SQL Server",            "trusted_connection": "yes",            "TrustServerCertificate": "yes",        },    )    engine = create_engine(        connection_url,        fast_executemany=True,    )#Store the number of rows loaded per table    load_summary = {}    try:         for f in csv_files:             table_name = f.stem.lower()             logging.info (f" Reading the file {table_name}")                          df = pd.read_csv(f)             logging.info (f"Loading data_frame {table_name} having {len(df)} rows and {len(df.columns)} columns")             df.to_sql(                name=table_name,                con=engine,                if_exists="replace",                index=False,                chunksize=1000,             )             load_summary[table_name] = len(df)             logging.info(                f"Successfully loaded to sql {len(df)} rows into table {table_name}")    finally:        engine.dispose()    return load_summarydef main():    parser = argparse.ArgumentParser(description="Fetching the data from the folder and converting to data frame")    parser.add_argument("--data-dir", default="../data", help="Where to fetch the data")    args = parser.parse_args()    try:        summary = load_data(args.data_dir)        if summary:            logging.info("Import summary:")            for table_name, row_count in summary.items():                logging.info(                    "%s: %d rows",                    table_name,                    row_count                )        else:            logging.info("No tables were loaded.")    except Exception:        logging.exception("Data loading failed.")        raiseif __name__ == "__main__":    main()